const files = [];
for (const item of $input.all()) {
  if (item.json.name && item.json.id) files.push({ name: item.json.name, id: item.json.id });
}
const excelFiles = files.filter(f => f.name.endsWith('.xlsx') || f.name.endsWith('.xls') || f.name.endsWith('.csv'));
const fileList = excelFiles.map((f, i) => `${i+1}. 📄 ${f.name}`).join('\n');
const sessionId = $('analyse,choix,ETL,conversation ?').first().json.sessionId;
return [{ json: { text: `📂 Fichiers disponibles :\n\n${fileList}\n\nLequel voulez-vous analyser ?`, files: excelFiles, type: 'choix_fichier', sessionId } }];

const spreadsheetId = items[0].json.id;
if (!spreadsheetId) throw new Error('Conversion échouée');
return [{ json: { spreadsheetId } }];

const sheets = items[0].json.sheets || [];
if (sheets.length === 0) throw new Error('Aucune feuille trouvée');
const spreadsheetId = $('extraire spreadsheet id').first().json.spreadsheetId;
return sheets.map(s => ({
  json: { spreadsheetId, sheetName: s.properties.title, sheetId: s.properties.sheetId, totalRows: s.properties.gridProperties.rowCount || 1000 }
}));

const data = $input.first().json;
const range = data.range || '';
const sheetName = range.split('!')[0].replace(/'/g, '') || 'sheet';
const values = data.values || [];

if (values.length < 2) return [{ json: {
  session_id: 'empty', sheet_name: sheetName, row_index: 0,
  row_data: '{}', is_cleaned: false, file_name: 'empty',
  created_at: new Date().toISOString()
}}];

const headers = values[0];
const dataRows = values.slice(1);

let sessionId = 'unknown';
let fileName = 'unknown';
try { sessionId = $('session id').first().json.sessionId; } catch(e) {}
try { fileName = $('extraire nom de fichier').first().json.fileName; } catch(e) {}

return dataRows.map((row, idx) => {
  const obj = {};
  headers.forEach((h, i) => {
    const key = String(h).replace(/[^a-zA-Z0-9_]/g, '_');
    obj[key] = row[i] !== undefined ? String(row[i]) : '';
  });
  return {
    json: {
      session_id: sessionId,
      file_name: fileName,
      sheet_name: sheetName,
      row_index: idx,
      row_data: JSON.stringify(obj),
      is_cleaned: false,
      created_at: new Date().toISOString()
    }
  };
});

const statsBefore = items.find(i => i.json.total_rows !== undefined)?.json || $('📊 BigQuery Stats avant cleaning').item.json;
const anomalies = $('🔍 BigQuery Détecter Anomalies').all().map(i => i.json);
const sample = $('📋 BigQuery Échantillon LLM').all().map(i => i.json);
const sessionId = $('🔧 Préparer Cleaning').item.json.sessionId;
return [{ json: { stats_before: statsBefore, anomalies, sample, sessionId } }];

