const raw = items[0].json.output || '{}';
let llmResult;
try { llmResult = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { llmResult = { quality_score: 75, anomalies_found: [], transformations_applied: [], recommendations: [], summary: raw }; }
const sessionId = $('🔧 Préparer Cleaning').item.json.sessionId;
const cleaningLog = { quality_score: llmResult.quality_score || 0, anomalies_found: llmResult.anomalies_found || [], transformations_applied: llmResult.transformations_applied || [], recommendations: llmResult.recommendations || [], storage: 'BigQuery', cleaned_at: new Date().toISOString() };
return [{ json: {
